import six
from abc import abstractmethod, ABCMeta


@six.add_metaclass(ABCMeta)
class BaseScfcErrorFixer(object):

    @abstractmethod
    def can_fix(self, validation_message):
        """Returns true if this fixer can fix given SCFC validation error/warning, false otherwise"""

    @abstractmethod
    def fix(self, validation_message, param_dictionary, scfc):
        """Fixes given SCFC validation error/warning in given SCFC xml using given parameter dictionary xml"""

    def _find_param_in_dictionary(self, dictionary, dist_name, list_name=None, param_name=None):
        if list_name is None:
            return dictionary.get_simple_param(dist_name, param_name)
        else:
            return dictionary.get_complex_param(dist_name, list_name, param_name)

    def _add_managed_object(self, scfc, managed_object_in_dictionary, dist_name):
        added_mo = scfc.add_managed_object(dist_name)
        lists_in_dictionary = managed_object_in_dictionary.get_all_list_params()
        params_in_dictionary = managed_object_in_dictionary.get_all_simple_params()
        self._add_lists_to_managed_object(added_mo, lists_in_dictionary)
        self._add_params_to_managed_object(added_mo, params_in_dictionary)
        self._fix_id_param_value(added_mo, managed_object_in_dictionary)

    def _add_lists_to_managed_object(self, managed_object, lists_in_dictionary):
        for list_in_dictionary in lists_in_dictionary:
            if list_in_dictionary.mandatory:
                self._add_list_to_managed_object(managed_object, list_in_dictionary)

    def _add_params_to_managed_object(self, managed_object, params_in_dictionary):
        for param_in_dictionary in params_in_dictionary:
            if param_in_dictionary.mandatory:
                self._add_param_to_managed_object(managed_object, param_in_dictionary)

    def _add_list_to_managed_object(self, managed_object, list_in_dictionary):
        added_list = managed_object.add_list_param(list_in_dictionary.name)
        params_in_dictionary = list_in_dictionary.get_all_params()
        for param_in_dictionary in params_in_dictionary:
            if param_in_dictionary.mandatory:
                self._add_param_to_list(added_list, param_in_dictionary)

    def _add_param_to_list(self, list_param, param_in_dictionary):
        default_value = self._get_default_value(param_in_dictionary)
        list_param.add_param(param_in_dictionary.name, default_value)

    def _add_param_to_managed_object(self, managed_object, param_in_dictionary):
        default_value = self._get_default_value(param_in_dictionary)
        multiple = param_in_dictionary.max_occurs > 1
        managed_object.add_param(param_in_dictionary.name, default_value, multiple=multiple)

    def _fix_id_param_value(self, managed_object, managed_object_in_dictionary):
        if managed_object_in_dictionary.has_id_param():
            id_param_name = managed_object_in_dictionary.get_id_param().name
            managed_object.find_param(id_param_name).value = managed_object.id

    def _get_default_value(self, param_in_dictionary):
        if param_in_dictionary.has_default_value():
            return param_in_dictionary.default_value
        elif param_in_dictionary.type == 'boolean':
            return 'false'
        elif param_in_dictionary.type == 'string':
            return self._create_default_string_value(param_in_dictionary)
        elif param_in_dictionary.is_enum():
            return param_in_dictionary.enum_values[0]
        elif param_in_dictionary.has_value_range():
            return param_in_dictionary.value_range.min
        else:
            return None

    def _create_default_string_value(self, param):
        if param.has_length_range():
            return 'x' * param.length_range.min_as_int
        else:
            return ''
